        .version("4.0.4")
        .about("Interact with the Pueue daemon")
        .long_about("Interact with the Pueue daemon\n\nUse the `--help` long form to get detailed help output on each subcommand!")
        .arg(Arg::new("verbose").short('v').long("verbose").action(ArgAction::Count).global(true).help("Verbose mode (-v, -vv, -vvv)"))
        .arg(Arg::new("color").long("color").value_name("COLOR").default_value("auto").global(true).value_parser(["auto","never","always"]).help("Colorize the output; auto enables color output when connected to a tty"))
        .arg(Arg::new("config").short('c').long("config").value_name("CONFIG").global(true).help("If provided, Pueue only uses this config file.\n\nThis path can also be set via the \"PUEUE_CONFIG_PATH\" environment variable. The\ncommandline option overwrites the environment variable!"))
        .arg(Arg::new("profile").short('p').long("profile").value_name("PROFILE").global(true).help("The name of the profile that should be loaded from your config file"))
        .subcommand(
            Command::new("add")
                .about("Enqueue a task for execution")
                .long_about("Enqueue a task for execution.\n\nThere're many different options when scheduling a task. Check the individual option help texts for\nmore information. Furthermore, please remember that scheduled commands are executed via your system\nshell. This means that the command needs proper shell escaping. The safest way to preserve shell\nescaping is to surround your command with quotes, for example:\n\npueue add 'ls $HOME && echo \"Some string\"'")
                .arg(Arg::new("working-directory").short('w').long("working-directory").value_name("working-directory").help("Specify current working directory"))
                .arg(Arg::new("escape").short('e').long("escape").action(ArgAction::SetTrue).help("Escape any special shell characters (\" \", \"&\", \"!\", etc.).\nBeware: This implicitly disables nearly all shell specific syntax (\"&&\", \"&>\")."))
                .arg(Arg::new("immediate").short('i').long("immediate").action(ArgAction::SetTrue).help("Immediately start the task"))
                .arg(Arg::new("follow").long("follow").action(ArgAction::SetTrue).help("Immediately follow a task, if it's started with --immediate"))
                .arg(Arg::new("stashed").short('s').long("stashed").action(ArgAction::SetTrue).help("Create the task in Stashed state.\n\nUseful to avoid immediate execution if the queue is empty."))
                .arg(Arg::new("delay").short('d').long("delay").value_name("delay").help("Prevents the task from being enqueued until 'delay' elapses. See \"enqueue\" for accepted\nformats"))
                .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Assign the task to a group.\n\nGroups kind of act as separate queues. All groups run in parallel and you can specify the\namount of parallel tasks for each group. If no group is specified, the default group will\nbe used.\n\nCreate groups via the `pueue group` subcommand"))
                .arg(Arg::new("after").short('a').long("after").value_name("after").num_args(1..).help("Start the task once all specified tasks have successfully finished.\n\nAs soon as one of the dependencies fails, this task will fail as well."))
                .arg(Arg::new("priority").short('o').long("priority").value_name("PRIORITY").help("Start this task with a higher priority.\n\nThe higher the number, the faster it will be processed."))
                .arg(Arg::new("label").short('l').long("label").value_name("LABEL").help("Add some information for yourself.\n\nThis string will be shown in the \"status\" table. There's no additional logic connected to\nit."))
                .arg(Arg::new("print-task-id").short('p').long("print-task-id").action(ArgAction::SetTrue).help("Only return the task id instead of a text.\n\nThis is useful when working with dependencies in scripts."))
                .arg(Arg::new("COMMAND").value_name("COMMAND").required(true).num_args(1..).help("The command to be added"))
        )
}

fn main() {
    let mut cmd = build_cli();
    let m = cmd.clone().try_get_matches_from(std::env::args());
    match m {
        Ok(matches) => {
            println!("ok {:?}", matches.subcommand_name());
        },
        Err(e) => {
            e.print().expect("print");
            std::process::exit(e.exit_code());
        }
    }
}
