fn main() {
    let args: Vec<String> = env::args().collect();

    if args.iter().any(|a| a == "--version" || a == "-V") {
        let known = ["add","remove","switch","stash","enqueue","start","restart","pause","kill","send","edit","env","group","status","log","follow","wait","clean","reset","shutdown","parallel","completions","help"];
        let mut found_sub = false;
        for arg in args.iter().skip(1) {
            if known.contains(&arg.as_str()) { found_sub = true; break; }
            if arg == "--version" || arg == "-V" { break; }
        }
        if args.len() == 2 && (args[1] == "--version" || args[1] == "-V") {
            println!("pueue 4.0.4");
            return;
        }
        if !found_sub {
            println!("pueue 4.0.4");
            return;
        }
    }

    if args.iter().any(|a| a == "--help" || a == "-h") || (args.len() >=2 && args[1]=="help") {
        print_help_for(&args);
        return;
    }

    let mut verbose: u8 = 0;
    let mut explicit_config: Option<String> = None;
    let mut profile: Option<String> = None;
    let mut color: String = "auto".to_string();
    let mut iter = args.iter().skip(1).peekable();
